import { readdirSync, renameSync, rmSync, existsSync } from 'node:fs';
import { join } from 'node:path';

const KEEP = 5;

function stamp(d: Date): string {
  return d.toISOString().slice(0, 10);
}

export function rotate(dir: string, now = new Date()): void {
  const current = join(dir, 'app.log');
  if (existsSync(current)) renameSync(current, join(dir, 'app-' + stamp(now) + '.log'));
  const old = readdirSync(dir)
    .filter((f) => /^app-\d{4}-\d{2}-\d{2}\.log$/.test(f))
    .sort()
    .reverse();
  for (const f of old.slice(KEEP)) rmSync(join(dir, f));
}

export function chunk<T>(items: readonly T[], size: number): T[][] {
  const out: T[][] = [];
  for (let i = 0; i < items.length; i += size) out.push(items.slice(i, i + size));
  return out;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}
